insert into product_options (product_id, key, label_de, price_delta_cents, sort_order) select id, 'intense_fragrance', 'Intensivduft', 3000, 0 from products where product_code='BUGO-PRM' on conflict (product_id, key) do update set label_de=excluded.label_de, price_delta_cents=excluded.price_delta_cents, sort_order=excluded.sort_order;
insert into product_scents (product_id, scent_id) select p.id, s.id from products p, scents s where p.product_code='BUGO-PRM' and s.code='frisch-ocean' on conflict do nothing;
